mapper.select:
select * from (select contract_code as contract_code, to_char(plan_date, 'YYYY-MM-dd') as plan_date, periods as periods, rent_amount as rent_amount, principal_amount as principal_amount, interest_amount as interest_amount, actual_repayment_date as actual_repayment_date, org_id as org_id, actual_repayment_principal_amount + actual_repayment_interes_amount as actual_amount, actual_repayment_principal_amount as actual_repayment_principal_amount, actual_repayment_interes_amount as actual_repayment_interes_amount, null as tax_value from eg_repayment_plan where del_flag = '0' and (
( org_id = #{orgId} and contract_code in (
#{contractCode}
) )
) ) u
and u.plan_date::date > #{startDate}
and #{endDate} > u.plan_date::date
order by u.org_id, u.contract_code, u.plan_date

select * from (select contract_code as contract_code, to_char(plan_date, 'YYYY-MM-dd') as plan_date, periods as periods, rent_amount as rent_amount, principal_amount as principal_amount, interest_amount as interest_amount, actual_repayment_date as actual_repayment_date, org_id as org_id, actual_repayment_principal_amount + actual_repayment_interes_amount as actual_amount, actual_repayment_principal_amount as actual_repayment_principal_amount, actual_repayment_interes_amount as actual_repayment_interes_amount, null as tax_value from eg_repayment_plan where del_flag = '0' and (
( org_id = #{orgId} and contract_code in (
#{contractCode}
) )
) union all select contract_code as contract_code, to_char(document_date, 'YYYY-MM-dd') as plan_date, null as periods, null as rent_amount, null as principal_amount, null as interest_amount, null as actual_repayment_date, org_id as org_id, null as actual_amount, null as actual_repayment_principal_amount, null as actual_repayment_interes_amount, sum(tax_value) as tax_value from eg_invoice_claim where voucher_id != 0 and del_flag = '0' and (
( org_id = #{orgId} and contract_code in (
#{contractCode}
) )
) group by contract_code, to_char(document_date, 'YYYY-MM-dd'), org_id) u
and u.plan_date::date > #{startDate}
and #{endDate} > u.plan_date::date
order by u.org_id, u.contract_code, u.plan_date
